// duet-dashboard: tiny status + control server for the Yoga Duet 7 home server.
//
// It serves one embedded UI (the same for the kiosk screen and any browser on
// the LAN or tailnet), a small JSON API and the live camera view. Standard
// library only.
package main

import (
	"context"
	"embed"
	"encoding/json"
	"errors"
	"io/fs"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
)

//go:embed web
var webFS embed.FS

// Service is one entry of the registry generated by the NixOS module.
type Service struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Icon        string `json:"icon"`
	Port        int    `json:"port"`
	Path        string `json:"path"`
	Unit        string `json:"unit"`
	Group       string `json:"group"`
}

// Config is read from the JSON file named by $DUET_CONFIG.
type Config struct {
	Hostname string    `json:"hostname"`
	Listen   string    `json:"listen"`
	Services []Service `json:"services"`
	// Live camera view: the relay's MJPEG socket, and who may watch it.
	CameraStream string   `json:"cameraStream"`
	CameraNets   []string `json:"cameraNets"`
	// Samsung TV remote (duet.tv); nil when not configured.
	TV *TVConfig `json:"tv"`
	// Voice assistant (duet.assistant); nil when not configured.
	Assistant *AssistantConfig `json:"assistant"`
}

func loadConfig() Config {
	cfg := Config{Hostname: "duet", Listen: "127.0.0.1:8088"}
	if h, err := os.Hostname(); err == nil {
		cfg.Hostname = h
	}
	path := os.Getenv("DUET_CONFIG")
	if path == "" {
		return cfg
	}
	b, err := os.ReadFile(path)
	if err != nil {
		log.Fatalf("read config: %v", err)
	}
	if err := json.Unmarshal(b, &cfg); err != nil {
		log.Fatalf("parse config: %v", err)
	}
	return cfg
}

func writeJSON(w http.ResponseWriter, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	_ = json.NewEncoder(w).Encode(v)
}

// sameOrigin rejects cross-site POSTs (a web page elsewhere on the LAN must
// not be able to dim the screen). Requests without an Origin header (curl)
// are allowed.
func sameOrigin(r *http.Request) bool {
	o := r.Header.Get("Origin")
	if o == "" {
		return true
	}
	return strings.HasSuffix(o, "://"+r.Host)
}

func main() {
	cfg := loadConfig()
	sampler := newSampler()
	go sampler.run()
	cam := newCamera(cfg)
	tv := newTV(cfg.TV)
	hasAssistant := false

	mux := http.NewServeMux()

	mux.HandleFunc("GET /api/status", func(w http.ResponseWriter, r *http.Request) {
		ctx, cancel := context.WithTimeout(r.Context(), 4*time.Second)
		defer cancel()
		st := collectStatus(ctx, cfg, sampler)
		st.Camera = cam.allowed(r)
		st.CameraViewers = cam.Viewers()
		st.TV = tv.Status()
		st.Assistant = hasAssistant
		writeJSON(w, st)
	})
	if cam != nil {
		mux.Handle("GET /api/camera", cam)
	}

	mux.HandleFunc("POST /api/brightness", func(w http.ResponseWriter, r *http.Request) {
		if !sameOrigin(r) {
			http.Error(w, "forbidden", http.StatusForbidden)
			return
		}
		var body struct {
			Percent int `json:"percent"`
		}
		if err := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1024)).Decode(&body); err != nil {
			http.Error(w, "bad request", http.StatusBadRequest)
			return
		}
		if err := setBrightness(body.Percent); err != nil {
			status := http.StatusInternalServerError
			if errors.Is(err, errNoBacklight) {
				status = http.StatusNotFound
			}
			http.Error(w, err.Error(), status)
			return
		}
		writeJSON(w, readBrightness())
	})

	if tv != nil {
		tv.register(mux)
	}
	hasAssistant = registerAssistant(mux, cfg.Assistant)

	sub, err := fs.Sub(webFS, "web")
	if err != nil {
		log.Fatal(err)
	}
	mux.Handle("/", http.FileServer(http.FS(sub)))

	srv := &http.Server{
		Addr:              cfg.Listen,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-stop
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()
		_ = srv.Shutdown(ctx)
	}()

	log.Printf("duet-dashboard listening on %s (%d services)", cfg.Listen, len(cfg.Services))
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatal(err)
	}
}
